def count_subarrays_with_sum(arr, target_sum):
    count = 0
    n = len(arr)
    for i in range(n):
        current_sum = 0
        for j in range(i, n):
            current_sum += arr[j]
            if current_sum == target_sum:
                count += 1
    return count

