def count_subarrays_with_sum(arr, target_sum):
    counts = {0: 1}
    prefix = 0
    result = 0
    for value in arr:
        prefix += value
        result += counts.get(prefix - target_sum, 0)
        counts[prefix] = counts.get(prefix, 0) + 1
    return result
